import { useEffect, useState } from 'react';
import { platform } from '@/lib/platform/index.js';

/**
 * Whether this device can listen at all, asked once (Say it). Undefined
 * while it is being asked: a recogniser that exists but cannot run is the
 * worst of the three states, so nothing is offered on a guess.
 */
export function useCanListen(asked: boolean): boolean | undefined {
  const [able, setAble] = useState<boolean | undefined>(undefined);
  useEffect(() => {
    if (!asked) return undefined;
    let live = true;
    platform.speech
      .available()
      .then((yes) => {
        if (live) setAble(yes);
      })
      .catch(() => {
        if (live) setAble(false);
      });
    return () => {
      live = false;
    };
  }, [asked]);
  return able;
}
